#!/usr/bin/env bash
# Danh mục đột biến cho các sửa HỒI QUY R-xx (21/10/2026): bản sửa 6f23ff3 (A-01…A-13) làm hỏng ở đúng những câu mà bản cha 1276b5f hỏi lại / không phán quyết —
# số trần nối với một lượng (dải, "hay", "chứ không phải") bị bỏ như nhãn (R-02), mốc thời gian chưa đọc được rơi về hôm nay / cả tháng (R-01), "mỗi ngày 3-4
# chuyến" đọc thành ngày 03/04 (R-05), câu quy trình thuần nêu hai thực thể bị hỏi lại oan (R-06), dạng ngày gõ nhầm bị bỏ (R-07), "..." làm mất phán quyết
# (R-10), số nhãn thành "con số xác nhận" khi câu không nêu lượng nào (R-04) và lượng trong tài liệu lọt khi chen dấu trang trí (R-03).
# Mỗi dòng: m <tệp> <chuỗi gốc> <chuỗi đột biến> <nhãn>. Kỳ vọng: mọi dòng in "BỊ BẮT" (rc=0). Chuỗi gốc là chuỗi con xuất hiện đúng 1 lần trong tệp; mã đổi thì
# sửa chuỗi theo mã mới — đừng xoá dòng cho xanh.
# Không đưa vào danh mục (đột biến tương đương, đã xét): bỏ `|| len(cs.doubts) > 0` của claimedValue — Handle đã hỏi lại mọi câu có mốc không kiểm được trước
# khi answerMetric chạy, nên claimedValue không bao giờ thấy doubts; bỏ `lo > 0 &&` của vòng contrastLeading — `lo > 0` chỉ để dừng ở đầu văn bản mà prevClauseStart
# cũng trả 0 ở đó; bỏ `gluedBefore` hay đổi độ dài phần năm của DashDateAt — các nhánh còn lại (`prev == '-'`, năm 4 chữ số do matchNumericDate đọc) đã phủ cùng đầu vào.
cd "$(dirname "$0")/../.." || exit 1
export PKGS="./core/pipeline/ ./data/normalization/ ./intelligence/intent/ ./reliability/validation/ ./tenants/construction/"
A=core/pipeline/ask.go D=data/normalization/datetime.go Q=data/normalization/qualifier.go I=intelligence/intent/intent.go K=reliability/validation/knowledge.go P=core/tenant/pack.go
m() { scripts/mutate.sh "$1" "$2" "$3" "$4"; echo "rc=$?"; }

